mapper.select:
SELECT 
FROM t_symbol_leverage_tier
WHERE symbol = #{symbol}
  AND group_code = #{groupCode}
  AND enabled = 1
ORDER BY notional_lower ASC

mapper.update:
UPDATE t_symbol_leverage_tier
SET enabled    = 0,
    updated_at = #{updatedAt}
WHERE id = #{id}

mapper.select:
SELECT 
FROM t_symbol_leverage_tier

    AND symbol = #{symbol}
    AND group_code = #{groupCode}

ORDER BY symbol ASC, group_code ASC, tier_no ASC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM t_symbol_leverage_tier

    AND symbol = #{symbol}
    AND group_code = #{groupCode}
